const weightInput=document.getElementById("weight"),heightInput=document.getElementById("height"),calculateBtn=document.getElementById("calculate-btn"),bmiResult=document.getElementById("bmi-result"),bmiAdvice=document.getElementById("bmi-advice"),bmiValue=document.getElementById("bmi-value"),bmiCategory=document.getElementById("bmi-category"),adviceText=document.getElementById("advice-text");function getBMICategory(e){return e<18.5?"Underweight":e<25?"Normal Weight":e<30?"Overweight":"Obesity"}function getBMIAdvice(e){return{Underweight:"You may want to gain weight through a balanced diet and exercise. Consider consulting with a healthcare provider.","Normal Weight":"Great! You're in the healthy weight range. Maintain your current lifestyle with regular exercise and balanced nutrition.",Overweight:"Consider losing weight through a combination of healthy diet and regular physical activity. Small changes can make a big difference.",Obesity:"It's recommended to lose weight for better health. Consider consulting with a healthcare provider for a personalized weight loss plan."}[e]||"Please consult with a healthcare provider for personalized advice."}function calculateBMI(){const e=parseFloat(weightInput.value),t=parseFloat(heightInput.value)/100;if(!e||!t)return void alert("Please enter valid weight and height values.");if(e<=0||t<=0)return void alert("Weight and height must be positive numbers.");const i=e/(t*t),n=getBMICategory(i),a=getBMIAdvice(n);bmiValue.textContent=i.toFixed(1),bmiCategory.textContent=n,adviceText.textContent=a;const r=document.querySelectorAll(".bmi-range");r.forEach(e=>e.classList.remove("current-range"));let l=0;i>=18.5&&i<25?l=1:i>=25&&i<30?l=2:i>=30&&(l=3),r[l].classList.add("current-range");const o=document.getElementById("bmi-result");o.style.background="Normal Weight"===n?"linear-gradient(135deg, #28a745, #20c997)":"Overweight"===n?"linear-gradient(135deg, #ffc107, #fd7e14)":"Obesity"===n?"linear-gradient(135deg, #dc3545, #138808)":"linear-gradient(135deg, #17a2b8, #20c997)",bmiResult.classList.remove("hidden"),bmiAdvice.classList.remove("hidden")}let timeout;calculateBtn.addEventListener("click",calculateBMI),[weightInput,heightInput].forEach(e=>{e.addEventListener("keypress",e=>{"Enter"===e.key&&calculateBMI()})}),[weightInput,heightInput].forEach(e=>{e.addEventListener("input",()=>{clearTimeout(timeout),timeout=setTimeout(()=>{weightInput.value&&heightInput.value&&calculateBMI()},500)})}),document.getElementById("back-to-tools-btn").addEventListener("click",function(e){e.preventDefault(),window.location.href="/#utility-tools-section"});